const validationErrors = [];
const contextIsObject = $json.context !== null
  && typeof $json.context === 'object'
  && !Array.isArray($json.context);
const context = contextIsObject ? $json.context : {};

if ($json.schema_version !== '1.0') {
  validationErrors.push('Invalid schema_version: expected 1.0.');
}
if ($json.route !== 'chapter.create.intake') {
  validationErrors.push('Invalid route: expected chapter.create.intake.');
}
if ($json.status !== 'ready') {
  validationErrors.push('Invalid status: expected ready.');
}
if (!contextIsObject) {
  validationErrors.push('Invalid context: expected an object.');
}
if (typeof context.workspace_uuid !== 'string' || !context.workspace_uuid.trim()) {
  validationErrors.push('context.workspace_uuid is required.');
}
if (typeof context.novel_uuid !== 'string' || !context.novel_uuid.trim()) {
  validationErrors.push('context.novel_uuid is required.');
}
if (!Number.isInteger(context.chapter_number) || context.chapter_number < 1) {
  validationErrors.push('context.chapter_number must be a positive integer.');
}
if (!Object.prototype.hasOwnProperty.call(context, 'chapter_title')) {
  validationErrors.push('context.chapter_title is required; an empty string is allowed.');
} else if (typeof context.chapter_title !== 'string') {
  validationErrors.push('context.chapter_title must be a string; an empty string is allowed.');
}

return [{
  json: {
    ...$json,
    is_valid: validationErrors.length === 0,
    status: validationErrors.length === 0 ? 'ready' : 'error',
    validation_errors: validationErrors,
  },
}];

function uuidHelper() {
  let timestamp = Date.now();
  let highResolution = typeof performance !== 'undefined' && typeof performance.now === 'function'
    ? Math.floor(performance.now() * 1000)
    : 0;

  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (token) => {
    let randomValue = Math.random() * 16;
    if (timestamp > 0) {
      randomValue = (timestamp + randomValue) % 16 | 0;
      timestamp = Math.floor(timestamp / 16);
    } else {
      randomValue = (highResolution + randomValue) % 16 | 0;
      highResolution = Math.floor(highResolution / 16);
    }
    return (token === 'x' ? randomValue : (randomValue & 0x3) | 0x8).toString(16);
  });
}

if ($json.is_valid !== true) {
  return [{ json: { ...$json } }];
}

const paddedNumber = String($json.chapter_number).padStart(4, '0');
const timestamp = new Date().toISOString();
const uuidSuffix = uuidHelper().replace(/-/g, '').slice(0, 8);

return [{
  json: {
    ...$json,
    chapter_uuid: `CHP-${uuidSuffix}`,
    chapter_slug: `chapter-${paddedNumber}`,
    chapter_order: $json.chapter_number,
    chapter_filename: `${paddedNumber}.md`,
    chapter_version: '1.0',
    created_at: timestamp,
    updated_at: timestamp,
    created_by: 'Novel Studio',
  },
}];

if ($json.is_valid !== true) {
  return [{
    json: {
      schema_version: '1.0',
      route: 'chapter.metadata.created',
      status: 'error',
      is_valid: false,
      validation_errors: $json.validation_errors ?? [],
    },
  }];
}

return [{
  json: {
    schema_version: '1.0',
    route: 'chapter.metadata.created',
    target: 'WF-004-P03',
    status: 'ready',
    is_valid: true,
    validation_errors: [],
    chapter: {
      chapter_uuid: $json.chapter_uuid,
      chapter_slug: $json.chapter_slug,
      chapter_number: $json.chapter_number,
      chapter_order: $json.chapter_order,
      chapter_title: $json.chapter_title,
      chapter_filename: $json.chapter_filename,
      chapter_version: $json.chapter_version,
      workspace_uuid: $json.workspace_uuid,
      novel_uuid: $json.novel_uuid,
      created_at: $json.created_at,
      updated_at: $json.updated_at,
      created_by: $json.created_by,
    },
  },
}];
